import hashlib, json, pathlib

root = pathlib.Path('.')
h = hashlib.sha256((root / 'benchmark/scripts/score.py').read_bytes()).hexdigest()
print('score.py sha256', h)
n = 0
bad = 0
for p in sorted(root.glob('benchmark/**/*.json')):
    t = p.read_text(errors='replace')
    if 'score.py' not in t:
        continue
    d = json.loads(t)

    def walk(o, path=''):
        global n, bad
        if isinstance(o, dict):
            vals = [v for v in o.values() if isinstance(v, str)]
            if any(v.endswith('score.py') for v in vals):
                for k, v in o.items():
                    if isinstance(v, str) and len(v) == 64 and all(c in '0123456789abcdef' for c in v):
                        n += 1
                        ok = v == h
                        bad += not ok
                        print(('OK  ' if ok else 'BAD ') + str(p) + ' ' + k + ' ' + v[:8])
            for k, v in o.items():
                if isinstance(v, str) and k.endswith('score.py') and len(v) == 64:
                    n += 1
                    ok = v == h
                    bad += not ok
                    print(('OK  ' if ok else 'BAD ') + str(p) + ' ' + k + ' ' + v[:8])
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    walk(d)
print('pins', n, 'bad', bad)
